#include <iostream>
#include <vector>
#include <list>
int main() {
    std::vector<int> v = {1,2,3,4,5,6};
    for (auto it = v.begin(); it != v.end(); )
        if (*it % 2 == 0) it = v.erase(it); else ++it;
    std::cout << "vector 删偶数: ";
    for (int x : v) std::cout << x << ' ';
    std::cout << '\n';
    std::list<int> L = {1,2,3,4};
    auto it = L.begin(); ++it;
    L.erase(L.begin());
    std::cout << "list erase 首元素后，原 it 仍指向 " << *it << '\n';
}
